-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW BRICKSURANCE.delegated_authority.vw_binder_status
COMMENT = 'Per-binder oversight summary the estate consumes: coverholder, utilisation (written premium vs estimate), bordereaux outstanding and open breaches. Publication contract for the delegated-authority workbench to re-point at. Grain: One row per binder.'
AS
SELECT
  b.binder_id, b.umr, ch.coverholder_id, p.name AS coverholder_name,
  b.premium_estimate,
  (SELECT COUNT(*) FROM BRICKSURANCE.delegated_authority.bordereau_submission s
   WHERE s.binder_id = b.binder_id AND s.bordereau_status_code IN ('RECEIVED','QUARANTINED')) AS bordereaux_outstanding,
  (SELECT COUNT(*) FROM BRICKSURANCE.delegated_authority.authority_breach ab
   WHERE ab.binder_id = b.binder_id AND ab.breach_status_code = 'OPEN') AS open_breaches
FROM BRICKSURANCE.delegated_authority.binding_authority b
JOIN BRICKSURANCE.delegated_authority.coverholder ch ON ch.coverholder_id = b.coverholder_id
JOIN BRICKSURANCE.party.party p ON p.party_id = ch.party_id;
